"""Запись в прод 15.10.2026 — «Прочие кабели» по сериям монтажных, «Многожильные» (аудит, серии и цены Паритета).

Запускать ТОЛЬКО после релиза кода ветки db-tabs-1015 (иначе новые строки лягут в «Прочие кабели») — скрипт сам
проверяет, что сервер знает новые серии, и иначе ничего не пишет. Порядок (live-data protocol, prod-reference-write):

  cd /opt/erp/app/deploy
  sudo -n docker compose --env-file /opt/erp/config/.env -f docker-compose.yml run --rm -T api python - dry   < этот файл
      → refused = 0, «пропуск» только у строк, которых нет на сервере
  sudo -n bash erp.sh backup-now
  sudo -n docker compose ... run --rm -T api python - apply < этот файл
  sudo -n docker compose ... run --rm -T api python - dry   < этот файл
      → новые строки «уже есть», правки — отказ «значение уже другое» / unchanged: записано

Ключ — «Марка» (натуральный ключ БД.ПРОВ), не ID. Ячейки листа идут загрузкой import_rows («old» = "" у пустой ячейки —
заполненная вернётся отказом; у правки аудита — текущее значение). Свои столбцы («Артикул поставщика», «Цена
поставщика, ₽/м», «Дата цены») загрузка не принимает — они пишутся правкой записи (тот же путь, что ячейка на экране,
со старым значением); столбец, которого нет, добавляется один раз (apply). Откатный журнал — docs/data/«Прочие кабели —
перенос и серии 15.10.csv», «Многожильные — аудит и серии 15.10.csv», «Цены поставщика 15.10.csv». Цена — каталожная
(прайс Паритета с НДС 22 % → ₽/м без НДС), не цена закупки: «Цена посл., ₽/м без НДС» (закупки) не трогается."""
